// FromJSON parses a JSON string and returns a Theme.
// On parse error, returns the default theme along with the error.
//
// Since: 2.2
func FromJSON(data string) (fyne.Theme, error) {
	return FromJSONReader(strings.NewReader(data))
}

// FromJSONReader parses JSON from an io.Reader and returns a Theme.
// On parse error, returns the default theme along with the error.
//
// Since: 2.2
func FromJSONReader(r io.Reader) (fyne.Theme, error) {
	var raw map[string]interface{}
	if err := json.NewDecoder(r).Decode(&raw); err != nil {
		return DefaultTheme(), err
	}

	theme := &jsonTheme{
		colors:      make(map[fyne.ThemeColorName]color.Color),
		colorsDark:  make(map[fyne.ThemeColorName]color.Color),
		colorsLight: make(map[fyne.ThemeColorName]color.Color),
		sizes:       make(map[fyne.ThemeSizeName]float32),
		fonts:       make(map[fyne.TextStyle]fyne.Resource),
		icons:       make(map[fyne.ThemeIconName]fyne.Resource),
		fallback:    DefaultTheme(),
	}

	// Parse colors
	if colors, ok := raw["Colors"].(map[string]interface{}); ok {
		for name, value := range colors {
			if hexStr, ok := value.(string); ok {
				if col, err := parseHexColor(hexStr); err == nil {
					theme.colors[fyne.ThemeColorName(name)] = col
				}
			}
		}
	}

	// Parse dark variant colors
	if colorsDark, ok := raw["Colors-dark"].(map[string]interface{}); ok {
		for name, value := range colorsDark {
			if hexStr, ok := value.(string); ok {
				if col, err := parseHexColor(hexStr); err == nil {
					theme.colorsDark[fyne.ThemeColorName(name)] = col
				}
			}
		}
	}

	// Parse light variant colors
	if colorsLight, ok := raw["Colors-light"].(map[string]interface{}); ok {
		for name, value := range colorsLight {
			if hexStr, ok := value.(string); ok {
				if col, err := parseHexColor(hexStr); err == nil {
					theme.colorsLight[fyne.ThemeColorName(name)] = col
				}
			}
		}
	}

	// Parse sizes
	if sizes, ok := raw["Sizes"].(map[string]interface{}); ok {
		for name, value := range sizes {
			var size float32
			switch v := value.(type) {
			case float64:
				size = float32(v)
			case float32:
				size = v
			case int:
				size = float32(v)
			default:
				continue
			}
			theme.sizes[fyne.ThemeSizeName(name)] = size
		}
	}

	// Parse fonts
	if fonts, ok := raw["Fonts"].(map[string]interface{}); ok {
		fontMap := map[string]fyne.TextStyle{
			"regular":     fyne.TextStyle{},
			"bold":        fyne.TextStyle{Bold: true},
			"italic":      fyne.TextStyle{Italic: true},
			"bolditalic":  fyne.TextStyle{Bold: true, Italic: true},
			"monospace":   fyne.TextStyle{Monospace: true},
		}

		for name, value := range fonts {
			if uriStr, ok := value.(string); ok {
				if uri, err := storage.ParseURI(uriStr); err == nil {
					if res, err := storage.LoadResourceFromURI(uri); err == nil {
						if style, ok := fontMap[strings.ToLower(name)]; ok {
							theme.fonts[style] = res
						}
					}
				}
			}
		}
	}

	// Parse icons
	if icons, ok := raw["Icons"].(map[string]interface{}); ok {
		for name, value := range icons {
			if uriStr, ok := value.(string); ok {
				if uri, err := storage.ParseURI(uriStr); err == nil {
					if res, err := storage.LoadResourceFromURI(uri); err == nil {
						theme.icons[fyne.ThemeIconName(name)] = res
					}
				}
			}
		}
	}

	return theme, nil
}

// parseHexColor parses a hex color string into a color.Color.
// Supports formats: #RGB, #RGBA, #RRGGBB, #RRGGBBAA (with or without #).
func parseHexColor(hex string) (color.Color, error) {
	hex = strings.TrimPrefix(hex, "#")

	var r, g, b, a uint8 = 0, 0, 0, 255

	switch len(hex) {
	case 3:
		// RGB -> RRGGBB
		vals := make([]uint8, 3)
		for i := 0; i < 3; i++ {
			v, err := strconv.ParseUint(string(hex[i]), 16, 8)
			if err != nil {
				return color.Transparent, fmt.Errorf("invalid hex color: %s", hex)
			}
			vals[i] = uint8(v)
			vals[i] = vals[i]<<4 | vals[i] // Expand single digit
		}
		r, g, b = vals[0], vals[1], vals[2]

	case 4:
		// RGBA -> RRGGBBAA
		vals := make([]uint8, 4)
		for i := 0; i < 4; i++ {
			v, err := strconv.ParseUint(string(hex[i]), 16, 8)
			if err != nil {
				return color.Transparent, fmt.Errorf("invalid hex color: %s", hex)
			}
			vals[i] = uint8(v)
			vals[i] = vals[i]<<4 | vals[i] // Expand single digit
		}
		r, g, b, a = vals[0], vals[1], vals[2], vals[3]

	case 6:
		// RRGGBB
		val, err := strconv.ParseUint(hex, 16, 32)
		if err != nil {
			return color.Transparent, fmt.Errorf("invalid hex color: %s", hex)
		}
		r = uint8(val >> 16)
		g = uint8(val >> 8)
		b = uint8(val)

	case 8:
		// RRGGBBAA
		val, err := strconv.ParseUint(hex, 16, 64)
		if err != nil {
			return color.Transparent, fmt.Errorf("invalid hex color: %s", hex)
		}
		r = uint8(val >> 24)
		g = uint8(val >> 16)
		b = uint8(val >> 8)
		a = uint8(val)

	default:
		return color.Transparent, fmt.Errorf("invalid hex color length: %s", hex)
	}

	return color.RGBA{R: r, G: g, B: b, A: a}, nil
}

