package binding

import (
	"errors"
	"fmt"

	"fyne.io/fyne/v2"
	"fyne.io/fyne/v2/storage"
)

// NewSprintf creates a new String binding that formats multiple bindings using fmt.Sprintf.
// When any source binding changes, the formatted string is automatically updated.
// Set() parses the string back using fmt.Sscanf and updates the source bindings.
//
// Since: 2.2
func NewSprintf(format string, bindings ...DataItem) String {
	s := &sprintfBinding{
		format:   format,
		bindings: bindings,
	}

	// Listen to all source bindings
	for _, b := range bindings {
		b.AddListener(s)
	}

	// Initialize formatted value
	s.updateFormatted()

	return s
}

type sprintfBinding struct {
	base

	format   string
	bindings []DataItem
	value    string
	lastErr  error
}

func (s *sprintfBinding) Get() (string, error) {
	s.lock.RLock()
	defer s.lock.RUnlock()

	if s.lastErr != nil {
		return "", s.lastErr
	}
	return s.value, nil
}

func (s *sprintfBinding) Set(str string) error {
	// Parse the string and set all source bindings
	values := make([]interface{}, len(s.bindings))

	for i, b := range s.bindings {
		switch b.(type) {
		case Bool:
			var val bool
			values[i] = &val
		case Bytes:
			// Bytes cannot be round-tripped
			return errors.New("cannot set Bytes binding from formatted string")
		case Float:
			var val float64
			values[i] = &val
		case Int:
			var val int
			values[i] = &val
		case Rune:
			var val rune
			values[i] = &val
		case String:
			var val string
			values[i] = &val
		case URI:
			var val string
			values[i] = &val
		default:
			return errors.New("unsupported binding type")
		}
	}

	// Scan the string
	_, err := fmt.Sscanf(str, s.format, values...)
	if err != nil {
		return err
	}

	// Set each binding
	for i, b := range s.bindings {
		switch binding := b.(type) {
		case Bool:
			err = binding.Set(*values[i].(*bool))
		case Float:
			err = binding.Set(*values[i].(*float64))
		case Int:
			err = binding.Set(*values[i].(*int))
		case Rune:
			err = binding.Set(*values[i].(*rune))
		case String:
			err = binding.Set(*values[i].(*string))
		case URI:
			uri, parseErr := storage.ParseURI(*values[i].(*string))
			if parseErr != nil {
				return parseErr
			}
			err = binding.Set(uri)
		}

		if err != nil {
			return err
		}
	}

	return nil
}

func (s *sprintfBinding) DataChanged() {
	s.updateFormatted()
	s.trigger()
}

func (s *sprintfBinding) updateFormatted() {
	s.lock.Lock()
	defer s.lock.Unlock()

	values := make([]interface{}, len(s.bindings))

	for i, b := range s.bindings {
		var val interface{}
		var err error

		switch binding := b.(type) {
		case Bool:
			val, err = binding.Get()
		case Bytes:
			val, err = binding.Get()
		case Float:
			val, err = binding.Get()
		case Int:
			val, err = binding.Get()
		case Rune:
			val, err = binding.Get()
		case String:
			val, err = binding.Get()
		case URI:
			uri, uriErr := binding.Get()
			if uriErr != nil {
				err = uriErr
			} else if uri != nil {
				val = uri.String()
			} else {
				val = ""
			}
		default:
			s.lastErr = errors.New("unsupported binding type")
			return
		}

		if err != nil {
			s.lastErr = err
			return
		}

		values[i] = val
	}

	s.value = fmt.Sprintf(s.format, values...)
	s.lastErr = nil
}

// StringToStringWithFormat creates a formatted String binding from another String binding.
// If the format is "%s", returns the original binding directly (optimization).
//
// Since: 2.2
func StringToStringWithFormat(str String, format string) String {
	if format == "%s" {
		return str
	}
	return NewSprintf(format, str)
}

