package layout

import (
	"fyne.io/fyne/v2"
)

// ResponsiveLayout is a layout that adapts based on available space.
// It uses different layouts for small, medium, and large screen sizes.
//
// Since: 2.2
type responsiveLayout struct {
	small  fyne.Layout
	medium fyne.Layout
	large  fyne.Layout

	smallBreakpoint  float32
	mediumBreakpoint float32
}

// NewResponsiveLayout creates a new responsive layout with different layouts for different screen sizes.
// The small layout is used when width < smallBreakpoint.
// The medium layout is used when smallBreakpoint <= width < mediumBreakpoint.
// The large layout is used when width >= mediumBreakpoint.
//
// If smallBreakpoint is 0, it defaults to 600.
// If mediumBreakpoint is 0, it defaults to 1024.
//
// Since: 2.2
func NewResponsiveLayout(small, medium, large fyne.Layout, smallBreakpoint, mediumBreakpoint float32) fyne.Layout {
	if smallBreakpoint == 0 {
		smallBreakpoint = 600
	}
	if mediumBreakpoint == 0 {
		mediumBreakpoint = 1024
	}

	return &responsiveLayout{
		small:            small,
		medium:           medium,
		large:            large,
		smallBreakpoint:  smallBreakpoint,
		mediumBreakpoint: mediumBreakpoint,
	}
}

func (r *responsiveLayout) selectLayout(size fyne.Size) fyne.Layout {
	if size.Width < r.smallBreakpoint {
		return r.small
	}
	if size.Width < r.mediumBreakpoint {
		return r.medium
	}
	return r.large
}

func (r *responsiveLayout) Layout(objects []fyne.CanvasObject, size fyne.Size) {
	layout := r.selectLayout(size)
	layout.Layout(objects, size)
}

func (r *responsiveLayout) MinSize(objects []fyne.CanvasObject) fyne.Size {
	// Use the small layout's min size as the baseline
	return r.small.MinSize(objects)
}

