package fyne

import (
	"time"
)

// Animation represents an animated sequence that changes a value over time.
//
// Since: 2.2
type Animation struct {
	Duration     time.Duration
	Tick         func(float32) // Called with value from 0.0 to 1.0
	Curve        AnimationCurve
	AutoReverse  bool
	RepeatCount  int // 0 = no repeat, -1 = infinite

	running       bool
	startTime     time.Time
	currentRepeat int
	reversed      bool
	stopChan      chan bool
}

// AnimationCurve defines how an animation progresses over time.
//
// Since: 2.2
type AnimationCurve int

const (
	// AnimationLinear progresses at a constant rate
	AnimationLinear AnimationCurve = iota
	// AnimationEaseIn starts slowly and accelerates
	AnimationEaseIn
	// AnimationEaseOut starts quickly and decelerates
	AnimationEaseOut
	// AnimationEaseInOut combines ease in and ease out
	AnimationEaseInOut
)

// NewAnimation creates a new animation with the specified duration and tick callback.
// The tick function will be called periodically with a value from 0.0 to 1.0
// representing the progress of the animation.
//
// Since: 2.2
func NewAnimation(d time.Duration, fn func(float32)) *Animation {
	return &Animation{
		Duration:    d,
		Tick:        fn,
		Curve:       AnimationLinear,
		AutoReverse: false,
		RepeatCount: 0,
		stopChan:    make(chan bool, 1),
	}
}

// Start begins the animation. If the animation is already running, this has no effect.
//
// Since: 2.2
func (a *Animation) Start() {
	if a.running {
		return
	}

	a.running = true
	a.startTime = time.Now()
	a.currentRepeat = 0
	a.reversed = false

	go a.run()
}

// Stop stops the animation.
//
// Since: 2.2
func (a *Animation) Stop() {
	if !a.running {
		return
	}

	a.stopChan <- true
	a.running = false
}

func (a *Animation) run() {
	ticker := time.NewTicker(time.Millisecond * 16) // ~60 FPS
	defer ticker.Stop()

	for {
		select {
		case <-a.stopChan:
			return
		case <-ticker.C:
			elapsed := time.Since(a.startTime)
			progress := float32(elapsed) / float32(a.Duration)

			if progress >= 1.0 {
				if a.AutoReverse && !a.reversed {
					a.reversed = true
					a.startTime = time.Now()
					a.Tick(1.0)
					continue
				}

				a.currentRepeat++
				if a.RepeatCount == -1 || a.currentRepeat < a.RepeatCount {
					a.startTime = time.Now()
					a.reversed = false
					a.Tick(0.0)
					continue
				}

				a.Tick(1.0)
				a.running = false
				return
			}

			if a.reversed {
				progress = 1.0 - progress
			}

			curved := a.applyCurve(progress)
			a.Tick(curved)
		}
	}
}

func (a *Animation) applyCurve(progress float32) float32 {
	switch a.Curve {
	case AnimationLinear:
		return progress
	case AnimationEaseIn:
		return progress * progress
	case AnimationEaseOut:
		return progress * (2.0 - progress)
	case AnimationEaseInOut:
		if progress < 0.5 {
			return 2.0 * progress * progress
		}
		return -1.0 + (4.0-2.0*progress)*progress
	default:
		return progress
	}
}

